  const catalogs = root.AtlasLocales || {};
  codes.forEach(code => { catalogs[code] = catalogs[code] || {}; });
  rows.forEach(([key, ...values]) => codes.forEach((code, index) => { catalogs[code][key] = values[index]; }));
